use verus::*;

verus! {

  // Given three side lengths a, b, c (each in [1,100]),
  // return the minimum number of increments by 1 to any side
  // to get a non-degenerate triangle, i.e.:
  // a + b > c && b + c > a && c + a > b
  //
  // If the triangle inequalities already hold strictly, return 0.
  //
  // All inputs and output are i8; the output is non-negative.
  //
  // We assume the inputs are in [1,100].
  //
  // The approach:
  // - Each triangle inequality must hold strictly.
  // - For each inequality of form x + y > z,
  //   if x + y <= z, then we minimally need to increment some side(s).
  // - It's optimal to just increment the largest side(s) to satisfy all inequalities.
  // - Because we can increment any side arbitrarily,
  //   the minimal steps is max(0, max_side - (sum_of_other_two) + 1)
  //
  // This formula comes from the key inequality that for a valid triangle:
  //   For any side s, s < sum_of_other_two
  // So if s >= sum_of_other_two,
  //   increments needed = s - sum_of_other_two + 1 to break equality and get strict inequality.

  spec fn is_valid_triangle(a: i32, b: i32, c: i32) -> bool {
    a + b > c && b + c > a && c + a > b
  }

  #[verifier(external_body)]
  #[verifier::external]
  fn max3(x: i32, y: i32, z: i32) -> i32 {
    if x >= y && x >= z {
      x
    } else if y >= x && y >= z {
      y
    } else {
      z
    }
  }

  fn solve(a: i8, b: i8, c: i8) -> i8
    ensures
      // Ensures result is >= 0
      result >= 0
    ensures
      // After adding result steps to some sides, can form strict triangle
      // Intuitively: result is the minimal increments needed
      old(is_valid_triangle(a as i32, b as i32, c as i32)) ==>
        result == 0
    decreases
      1
  {
    let a32: i32 = a as i32;
    let b32: i32 = b as i32;
    let c32: i32 = c as i32;

    // Check if already valid triangle
    if is_valid_triangle(a32, b32, c32) {
      return 0;
    }

    // Compute maximum side
    let m = max3(a32, b32, c32);

    // Sum of all sides
    let sum = a32 + b32 + c32;

    // The sum of the other two sides is sum - m
    let other_sum = sum - m;

    // increments needed to make triangle inequality strict for largest side:
    // m < other_sum  is required.
    // If m >= other_sum, steps = m - other_sum + 1
    let steps = if m >= other_sum { m - other_sum + 1 } else { 0 };

    // Cannot be negative, cast back to i8
    steps as i8
  }
}